mapper.update:
UPDATE book_info
SET status = #{status},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE book_info
SET audit_status = #{auditStatus},
    audit_remark = #{auditRemark},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE book_info
SET audit_status = 1,
    audit_remark = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND audit_status <> 1

UPDATE book_info
SET visit_count = visit_count + 1
WHERE id = #{id}

UPDATE book_info
SET word_count = #{wordCount}
WHERE id = #{id}

UPDATE book_info
SET update_time = #{updateTime}
WHERE id = #{id}

UPDATE book_info b
SET b.comment_count = (
    SELECT COUNT(*) FROM book_comment c
    WHERE c.book_id = b.id AND c.audit_status = 1
)
WHERE b.id = #{bookId}

